// === Jarvis "leader -> branch" robot-error bot ===
const REG_URL = "https://raw.githubusercontent.com/ntvn2022/z-bee-duo/claude/esp32-s3-touch-screen-wwelt1/xiaozhi-ai/machines/registry.json";
const body = ($input.first().json.body) || $input.first().json || {};
const text = (body.text || "").toString().trim();
const history = body.history || [];
const MODEL = body.model || "gemini-2.5-flash";
const GEMINI_KEY = body.gemini_key || $env.GEMINI_API_KEY || "";

const out = (o) => [{ json: o }];
if (!text) return out({ reply: "Bạn muốn hỏi lỗi/cảnh báo của máy nào, mã số mấy?", need: "text" });

// exit robot mode
if (/(k[eế]t th[uú]c robot|tho[aá]t robot|d[uừ]ng robot)/i.test(text))
  return out({ reply: "Đã thoát chế độ tra cứu lỗi máy.", mode: "exit" });

const norm = (s) => (s||"").toLowerCase().normalize("NFD").replace(/[̀-ͯ]/g,"");
const t = norm(text);

// 1) LEADER: fetch registry + pick machine by alias
const registry = await this.helpers.httpRequest({ url: REG_URL, json: true });
let machine = null;
for (const m of registry) if ((m.aliases||[]).some(a => t.includes(norm(a)))) { machine = m; break; }
if (!machine) {
  if (registry.length === 1) machine = registry[0];   // only one machine -> assume it
  else return out({ reply: "Bạn hỏi về máy nào? Hiện có: " + registry.map(m=>m.name_vi).join(", ") + ".", need: "machine" });
}

// 2) extract code number
const cm = t.match(/(\d{1,3})/);
if (!cm) return out({ reply: `Bạn hỏi mã lỗi (error) hay cảnh báo (alarm) số mấy của ${machine.name_vi}?`, need: "code" });
const num = parseInt(cm[1], 10);

// type hint from wording
const wantAlarm = /(alarm|canh bao)/.test(t);
const wantError = /(error|loi)/.test(t);

// 3) BRANCH: fetch that machine's tables, find matches for the code
const rows = await this.helpers.httpRequest({ url: machine.tables_url, json: true });
const matches = rows.filter(r => parseInt(r.code,10) === num);
if (!matches.length)
  return out({ reply: `Không thấy mã ${num} cho ${machine.name_vi}. Bạn kiểm tra lại số giúp mình nhé.`, need: "code" });

const errT = machine.error_types||[], almT = machine.alarm_types||[];
const grp = (ty) => errT.includes(ty) ? "error" : (almT.includes(ty) ? "alarm" : "other");
const hasErr = matches.some(m=>grp(m.type)==="error");
const hasAlm = matches.some(m=>grp(m.type)==="alarm");
let selected = matches, askType = false;
if (wantError && !wantAlarm) selected = matches.filter(m=>grp(m.type)==="error");
else if (wantAlarm && !wantError) selected = matches.filter(m=>grp(m.type)==="alarm");
else if (hasErr && hasAlm) askType = true;      // ambiguous: summarize both + ask
if (!selected.length) selected = matches;

// 4) build prompt + call Gemini to phrase the answer
const ctx = selected.map(m=>`[${m.type} ${m.code}] ${m.content}`).join("\n");
let sys = `Bạn là trợ lý kỹ thuật cho ${machine.name_vi}. Trả lời bằng ngôn ngữ của người hỏi (mặc định tiếng Việt), NGẮN GỌN, đúng thứ tự: 1) Mô tả lỗi 2) Nguyên nhân 3) Cách khắc phục. `;
if (askType) sys += `Mã ${num} tồn tại ở CẢ cảnh báo (alarm) LẪN lỗi (error) — hãy tóm tắt cả hai loại rồi HỎI LẠI người dùng muốn loại nào. `;
sys += `Cuối câu trả lời LUÔN kèm 1 câu nhắc: cần phân biệt "cảnh báo (alarm)" và "lỗi (error)" vì là hai khái niệm khác nhau. CHỈ dùng dữ liệu sau:\n${ctx}`;

let reply = "";
if (GEMINI_KEY) {
  try {
    const g = await this.helpers.httpRequest({
      method: "POST",
      url: `https://generativelanguage.googleapis.com/v1beta/models/${MODEL}:generateContent?key=${GEMINI_KEY}`,
      body: { contents: [{ parts: [{ text: sys + `\n\nCâu hỏi: ${text}` }] }] },
      json: true,
    });
    reply = g?.candidates?.[0]?.content?.parts?.[0]?.text || "";
  } catch (e) { reply = ""; }
}
if (!reply) {
  reply = selected.map(m=>`${m.type} ${m.code}: ${m.content}`).join("  |  ")
    + "  (Lưu ý: cảnh báo/alarm và lỗi/error là hai loại khác nhau.)";
}
return out({ reply, machine: machine.id, code: num, types: selected.map(m=>m.type), askType });
